        assertTrue(released.reconciliation().stream().allMatch(ReconciliationEntry::matched));

        // 回执头只数超过判定数：同样勾稽不等，拒绝出厂
        declareOk("d-2", "B-OVER", List.of("H1"));
        preQuarantineOk("B-OVER", "pq-2");
